import React,{useEffect,useMemo,useState} from 'react';
import {Alert,Image,KeyboardAvoidingView,Modal,Platform,ScrollView,StatusBar,StyleSheet,Text,TextInput,TouchableOpacity,View} from 'react-native';
import {NavigationContainer,useNavigation} from '@react-navigation/native'; import {createNativeStackNavigator} from '@react-navigation/native-stack'; import {SafeAreaProvider} from 'react-native-safe-area-context'; import {StatusBar as ExpoStatusBar} from 'expo-status-bar';
import {MarketplaceProvider,useMarketplace} from './src/state/Marketplace'; import {Application,Booking,FieldKey,Service} from './src/types'; import {quote} from './src/utils/pricing';
const Stack=createNativeStackNavigator();
const C={bg:'#f5f7f2',ink:'#192d2a',muted:'#71817c',green:'#176e59',lime:'#d8f0a2',card:'#fff',line:'#e5ebe5',orange:'#f5b76b',red:'#ad4a3b'};
const servicePhotos:Record<string,number>={
 home:require('./assets/services/home-cleaning.jpg'),bath:require('./assets/services/bathroom-cleaning.jpg'),kitchen:require('./assets/services/kitchen-cleaning.jpg'),chimney:require('./assets/services/kitchen-cleaning.jpg'),
 sofa:require('./assets/services/home-interior.jpg'),carpet:require('./assets/services/home-interior.jpg'),move:require('./assets/services/home-interior.jpg'),postreno:require('./assets/services/home-cleaning.jpg'),
 tank:require('./assets/services/home-cleaning.jpg'),sump:require('./assets/services/home-cleaning.jpg'),balcony:require('./assets/services/home-cleaning.jpg'),windows:require('./assets/services/home-cleaning.jpg'),floor:require('./assets/services/home-interior.jpg')
};
const servicePhoto=(id:string)=>servicePhotos[id]||servicePhotos.home;
const shortWeekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const shortMonths=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function availableDays(service:Service){const base=new Date();base.setHours(0,0,0,0);return Array.from({length:15},(_,offset)=>{const value=new Date(base);value.setDate(base.getDate()+offset);return {offset,value,label:`${shortWeekdays[value.getDay()]}, ${value.getDate()} ${shortMonths[value.getMonth()]}`,day:value.getDate(),weekday:shortWeekdays[value.getDay()],month:shortMonths[value.getMonth()]}}).filter(day=>day.offset>=service.leadDays&&service.weekdays.includes(day.value.getDay())).slice(0,7)}
const money=(n:number)=>`₹${Math.round(n).toLocaleString('en-IN')}`;
const statusText=(status:string)=>({awaiting_assignment:'Finding a cleaner',awaiting_employee_acceptance:'Waiting for cleaner',assigned:'Cleaner accepted',en_route:'On the way',arrived:'Cleaner arrived',in_progress:'Cleaning in progress',completed:'Completed',cancelled:'Cancelled'} as Record<string,string>)[status]||status.replaceAll('_',' ');
function Txt({children,size=15,color=C.ink,bold=false,style}:any){return <Text style={[{fontSize:size,color,fontWeight:bold?'700':'400'},style]}>{children}</Text>}
function Btn({title,onPress,secondary=false,disabled=false}:any){return <TouchableOpacity disabled={disabled} onPress={onPress} style={[s.btn,secondary&&s.btnSecondary,disabled&&{opacity:.45}]}><Txt color={secondary?C.green:'#fff'} bold>{title}</Txt></TouchableOpacity>}
function Chip({label,selected,onPress,disabled=false}:any){return <TouchableOpacity disabled={disabled} onPress={onPress} style={[s.chip,selected&&s.chipOn,disabled&&{opacity:.35}]}><Txt size={13} color={selected?'#fff':C.ink} bold={selected}>{label}</Txt></TouchableOpacity>}
function Card({children,style}:any){return <View style={[s.card,style]}>{children}</View>}
function Heading({title,subtitle}:any){return <View style={{marginTop:22,marginBottom:12}}><Txt size={21} bold>{title}</Txt>{subtitle&&<Txt color={C.muted} style={{marginTop:4}}>{subtitle}</Txt>}</View>}
function Field({label,value,onChangeText,placeholder,keyboardType}:any){return <View style={{marginBottom:12}}><Txt size={13} bold style={{marginBottom:6}}>{label}</Txt><TextInput value={value} onChangeText={onChangeText} placeholder={placeholder||label} placeholderTextColor="#9aa8a1" keyboardType={keyboardType} style={s.input}/></View>}
function FooterBar(){const navigation=useNavigation<any>();return <View style={s.footerBar}><TouchableOpacity style={s.footerItem} onPress={()=>navigation.navigate('Home')}><Txt size={12} color={C.green} bold>⌂</Txt><Txt size={10} color={C.green} bold>Home</Txt></TouchableOpacity><TouchableOpacity style={s.footerItem} onPress={()=>navigation.navigate('Bookings')}><Txt size={12} color={C.muted} bold>✓</Txt><Txt size={10} color={C.muted} bold>Bookings</Txt></TouchableOpacity><TouchableOpacity style={s.footerItem} onPress={()=>navigation.navigate('Employee')}><Txt size={12} color={C.muted} bold>✦</Txt><Txt size={10} color={C.muted} bold>Cleaner</Txt></TouchableOpacity><TouchableOpacity style={s.footerItem} onPress={()=>navigation.navigate('Admin')}><Txt size={12} color={C.muted} bold>◌</Txt><Txt size={10} color={C.muted} bold>Admin</Txt></TouchableOpacity></View>}
function Screen({children}:any){return <KeyboardAvoidingView style={{flex:1,backgroundColor:C.bg}} behavior={Platform.OS==='ios'?'padding':undefined}><View style={{flex:1}}><ScrollView stickyHeaderIndices={[0]} contentContainerStyle={[s.content,{paddingBottom:96}]} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>{children}</ScrollView><FooterBar/></View></KeyboardAvoidingView>}
function Header({title,back}:any){return <View style={[s.header,{backgroundColor:C.bg,paddingVertical:10,borderBottomWidth:1,borderBottomColor:C.line}]}><Txt size={23} bold>{title}</Txt>{back&&<TouchableOpacity onPress={back}><Txt color={C.green} bold>← Back</Txt></TouchableOpacity>}</View>}
function Root(){return <View style={s.appShell}><NavigationContainer><Stack.Navigator screenOptions={{headerShown:false,contentStyle:{backgroundColor:C.bg},animation:'slide_from_right'}}><Stack.Screen name="Home" component={Home}/><Stack.Screen name="Service" component={ServicePage}/><Stack.Screen name="Book" component={BookingFlow}/><Stack.Screen name="Bookings" component={BookingsPage}/><Stack.Screen name="Detail" component={BookingDetail}/><Stack.Screen name="Employee" component={EmployeePage}/><Stack.Screen name="Admin" component={AdminGate}/><Stack.Screen name="EditService" component={ServiceEditor}/></Stack.Navigator></NavigationContainer></View>}
export default function App(){
  useEffect(()=>{
    if (Platform.OS === 'web') {
      const previousBodyBg = document.body.style.backgroundColor;
      const previousBodyMargin = document.body.style.margin;
      const previousBodyOverflow = document.body.style.overflow;
      document.body.style.backgroundColor = '#dfe7dc';
      document.body.style.margin = '0';
      document.body.style.overflow = 'hidden';
      return ()=>{
        document.body.style.backgroundColor = previousBodyBg;
        document.body.style.margin = previousBodyMargin;
        document.body.style.overflow = previousBodyOverflow;
      };
    }
    return undefined;
  }, []);
  return <SafeAreaProvider><MarketplaceProvider><View style={s.pageWrap}><ExpoStatusBar style="dark"/><Root/></View></MarketplaceProvider></SafeAreaProvider>
}

function Home({navigation}:any){const {services,user,setUser}=useMarketplace();const [search,setSearch]=useState('');const [filter,setFilter]=useState('All');const [showLogin,setShowLogin]=useState(true);const [step,setStep]=useState<'phone'|'otp'|'done'>('phone');const [phone,setPhone]=useState('');const [otp,setOtp]=useState('');const [name,setName]=useState('');const shown=services.filter(x=>x.active&&!x.paused&&(filter==='All'||x.category===filter)&&x.name.toLowerCase().includes(search.toLowerCase()));
 const proceed=()=>{if(!/^\d{10}$/.test(phone)){Alert.alert('Check your number','Enter a 10-digit demo phone number.');return}setStep('otp')};
 return <><Screen><View style={[s.homeTop,{backgroundColor:C.bg,paddingVertical:12,marginTop:-8,borderBottomWidth:1,borderBottomColor:C.line}]}><View><Txt size={11} color={C.muted} style={{letterSpacing:1.2}}>{'YOUR HOME, A LITTLE LIGHTER'.toUpperCase()}</Txt><View style={{flexDirection:'row',alignItems:'center',marginTop:4}}><Txt size={28} bold>Tidyday</Txt><View style={s.brandBadge}><Txt size={12} color={C.green} bold>✦</Txt></View></View></View><TouchableOpacity onPress={()=>navigation.navigate('Bookings')} style={s.avatar}><Txt bold color={C.green}>{user?'●':'♡'}</Txt></TouchableOpacity></View><View style={s.premiumLocation}><Txt color={C.green}>⌖ Chennai, Tamil Nadu</Txt></View><View style={s.roleDock}><TouchableOpacity onPress={()=>navigation.navigate('Employee')} style={s.roleDockItem}><Txt size={13}>✦</Txt><Txt size={12} color={C.green} bold>Cleaner portal</Txt></TouchableOpacity><TouchableOpacity onPress={()=>navigation.navigate('Admin')} style={s.roleDockItem}><Txt size={13}>◌</Txt><Txt size={12} color={C.green} bold>Admin studio</Txt></TouchableOpacity></View><TouchableOpacity style={s.location}><Txt color={C.green}>⌖  Chennai, Tamil Nadu  ▾</Txt></TouchableOpacity><TextInput value={search} onChangeText={setSearch} placeholder="What would you like cleaned?" style={s.search}/><View style={s.hero}><Txt size={12} color="#daefad" bold>THE TIDYDAY EDIT</Txt><Txt size={25} color="#fff" bold style={{marginTop:8}}>Make room for{ '\n'}a slower Sunday.</Txt><Txt color="#e5efe9" style={{marginTop:8}}>A thoughtful clean, right on schedule.</Txt><TouchableOpacity onPress={()=>navigation.navigate('Service',{service:services[0]})} style={s.heroBtn}><Txt color={C.ink} bold>Explore home cleaning  →</Txt></TouchableOpacity></View><View style={s.rowBetween}><Heading title="Cleaning, your way"/><TouchableOpacity onPress={()=>navigation.navigate('Bookings')}><Txt color={C.green} bold>My bookings</Txt></TouchableOpacity></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{maxHeight:42}}>{['All','Home','Room','Specialty','Fabric'].map(c=><Chip key={c} label={c} selected={filter===c} onPress={()=>setFilter(c)}/>)}</ScrollView><Heading title="Popular near you" subtitle={`${shown.length} services · illustrative demo prices`}/>{shown.length>0&&<TouchableOpacity onPress={()=>navigation.navigate('Service',{service:shown[0]})}><ServiceCard service={shown[0]} featured/></TouchableOpacity>}<View style={s.serviceGrid}>{shown.slice(1).map(service=><TouchableOpacity key={service.id} style={s.serviceGridItem} onPress={()=>navigation.navigate('Service',{service})}><ServiceCard service={service}/></TouchableOpacity>)}</View>{!shown.length&&<Empty text="No services match your search."/>}</Screen>
 <Modal visible={showLogin&&!user} animationType="slide" transparent onRequestClose={()=>setShowLogin(false)}><View style={s.scrim}><View style={s.sheet}><View style={s.grabber}/><Txt size={24} bold>{step==='done'?'You’re all set':step==='otp'?'Verify your number':'A cleaner home starts here'}</Txt><Txt color={C.muted} style={{marginTop:7,marginBottom:18}}>{step==='otp'?'Demo only · no message will be sent. Enter any six digits.':step==='done'?'Your demo profile is ready. Explore at your own pace.':'Sign in to keep your bookings together.'}</Txt>{step==='phone'&&<><Field label="Mobile number" value={phone} onChangeText={setPhone} keyboardType="phone-pad"/><Btn title="Continue with phone" onPress={proceed}/></>}{step==='otp'&&<><Field label="Six-digit demo OTP" value={otp} onChangeText={setOtp} keyboardType="number-pad"/><Btn title="Verify demo code" onPress={()=>{if(!/^\d{6}$/.test(otp)){Alert.alert('Enter six digits');return}setUser({name:name||'Demo customer',phone});setStep('done')}}/></>}{step==='done'&&<Btn title="Start exploring" onPress={()=>setShowLogin(false)}/>}<TouchableOpacity style={{padding:12,alignItems:'center'}} onPress={()=>setShowLogin(false)}><Txt color={C.green} bold>Skip and explore</Txt></TouchableOpacity><View style={s.rowBetween}><TouchableOpacity onPress={()=>{setShowLogin(false);navigation.navigate('Employee')}}><Txt color={C.muted}>Employee access</Txt></TouchableOpacity><TouchableOpacity onPress={()=>{setShowLogin(false);navigation.navigate('Admin')}}><Txt color={C.muted}>Admin access</Txt></TouchableOpacity></View></View></View></Modal></>}
function ServiceCard({service,featured=false}:any){return <View style={[s.photoServiceCard,featured&&s.featuredServiceCard]}><View style={[s.photoFrame,featured&&s.featuredPhotoFrame]}><Image source={servicePhoto(service.id)} style={s.servicePhoto} resizeMode="cover" accessibilityLabel={`${service.name} sample service photo`}/>{featured&&<View style={s.photoShade}/>}<View style={s.categoryPill}><Txt size={11} color="#fff" bold>{service.category.toUpperCase()}</Txt></View>{featured&&<View style={s.featuredPrice}><Txt color="#fff" bold>{money(service.price)}+</Txt></View>}</View><View style={s.serviceCardBody}><View style={s.rowBetween}><Txt size={featured?19:15} bold style={[s.serviceTitle,{flex:1}]} numberOfLines={2}>{service.name}</Txt>{!featured&&<Txt color={C.green} bold size={13}>{money(service.price)}+</Txt>}</View><Txt size={12} color={C.muted} style={s.serviceDescription} numberOfLines={2}>{service.description}</Txt><View style={s.serviceMeta}><Txt size={11} color={C.muted}>◷ {Math.round(service.duration/60)}h {service.duration%60?`${service.duration%60}m`:''}</Txt><Txt size={11} color={C.green} bold>View details →</Txt></View></View></View>}
function emoji(category:string){return category==='Home'?'⌂':category==='Room'?'◈':category==='Fabric'?'▧':'◉'}
function ServicePage({route,navigation}:any){const {services}=useMarketplace();const service:Service=services.find(x=>x.id===route.params.service.id)||route.params.service;return <Screen><Header title="Service details" back={()=>navigation.goBack()}/><View style={s.detailHero}><Image source={servicePhoto(service.id)} style={s.detailHeroPhoto} resizeMode="cover"/><View style={s.detailHeroShade}/><View style={s.detailHeroCopy}><Txt size={11} color="#e5f6dc" bold>{service.category.toUpperCase()} SERVICE</Txt><Txt size={25} color="#fff" bold style={{marginTop:5}}>{service.name}</Txt><Txt color="#fff" style={{marginTop:8}}>{service.duration} min · booking from {service.leadDays===0?'today':'tomorrow'}</Txt></View></View><Card style={{marginTop:14}}><View style={s.rowBetween}><View><Txt color={C.muted} size={12}>STARTING FROM</Txt><Txt size={25} color={C.green} bold>{money(service.price)}{service.discount?`  ·  ${service.discount}% off`:''}</Txt></View><View style={s.detailIcon}><Txt size={24}>{emoji(service.category)}</Txt></View></View><Txt color={C.muted} style={{marginTop:10}}>{service.description}</Txt></Card><Heading title="Included"/>{service.includes.map(x=><Txt key={x} style={s.bullet}>✓  {x}</Txt>)}<Heading title="Not included"/>{service.excludes.map(x=><Txt key={x} color={C.muted} style={s.bullet}>·  {x}</Txt>)}{!!service.addons.length&&<><Heading title="Popular add-ons"/>{service.addons.map(a=><Txt key={a.id} style={s.bullet}>{a.name} · {money(a.price)}</Txt>)}</>}<Card style={{marginTop:20}}><Txt bold>Good to know</Txt><Txt color={C.muted} style={{marginTop:6}}>Illustrative prices and availability for this static demo. Final quote reflects your selections.</Txt></Card><Btn title="Configure and book" onPress={()=>navigation.navigate('Book',{serviceId:service.id})}/></Screen>}

const options:Record<FieldKey,string[]>={property:['Apartment','Independent house','Villa','Duplex','Other'],occupancy:['Occupied home','Vacant / empty'],bhk:['Studio / 1 BHK','2 BHK','3 BHK','4 BHK','5+ BHK'],area:['Under 800 sq ft','800–1,200 sq ft','1,201–1,800 sq ft','Over 1,800 sq ft'],floors:['1 floor','2 floors','3 floors','4+ floors'],bathrooms:['1 bathroom','2 bathrooms','3 bathrooms','4+ bathrooms'],condition:['Regular','Heavy dirt / grease','Move-in / move-out','Post-renovation']};const fieldLabels:Record<FieldKey,string>={property:'Property type',occupancy:'Occupancy',bhk:'Home size',area:'Built-up area',floors:'Number of floors',bathrooms:'Bathrooms',condition:'Cleaning condition'};
function BookingFlow({route,navigation}:any){const {services,user,addBooking,setUser,bookings}=useMarketplace();const service=services.find(x=>x.id===route.params.serviceId)!;const scheduleDays=availableDays(service);const [req,setReq]=useState<Record<string,string>>({});const [addons,setAddons]=useState<string[]>([]);const [date,setDate]=useState(scheduleDays[0]?.label||'No available date');const [slot,setSlot]=useState(service.slots[0]||'09:00');const [name,setName]=useState(user?.name||'');const [phone,setPhone]=useState(user?.phone||'');const [house,setHouse]=useState('');const [street,setStreet]=useState('');const [area,setArea]=useState('Adyar');const [city,setCity]=useState('Chennai');const [pin,setPin]=useState('600020');const [landmark,setLandmark]=useState('');const [step,setStep]=useState(0);const [guestAuth,setGuestAuth]=useState(false);const [otp,setOtp]=useState('');const [saved,setSaved]=useState(false);
 const price=quote(service,req,addons);const occupied=(d:string,t:string)=>bookings.some(b=>b.serviceId===service.id&&b.date===d&&b.slot===t&&b.status!=='cancelled');const toggle=(id:string)=>setAddons(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);
 const confirm=()=>{if(!name.trim()||!/^\d{10}$/.test(phone)||!house.trim()||!street.trim()||!/^[0-9]{6}$/.test(pin)){Alert.alert('Complete your details','Add your name, 10-digit phone, house number, street and 6-digit PIN.');return}if(!user){setGuestAuth(true);return}create()};
 const create=()=>{if(saved)return;const id=`TD-${Math.random().toString(36).slice(2,7).toUpperCase()}`;const address=`${house}, ${street}, ${area}, ${city} ${pin}${landmark?`, near ${landmark}`:''}`;const b:Booking={id,serviceId:service.id,serviceName:service.name,customerName:name,phone,address,area,date,slot,requirements:{...req},addons: [...addons],breakdown:price.lines.map(x=>({...x})),total:price.total,status:'awaiting_assignment',createdAt:new Date().toISOString(),timeline:['Booking placed','Finding a professional']};addBooking(b);setSaved(true);Alert.alert('Booking confirmed',`${id} · ${date} at ${slot}\n${money(price.total)} · Payment integration coming later`,[{text:'View booking',onPress:()=>navigation.replace('Detail',{bookingId:id})}]);};
 return <><Screen><Header title={`Book · ${service.name}`} back={()=>navigation.goBack()}/><View style={s.steps}>{['Details','Schedule','Address','Review'].map((x,i)=><View key={x} style={{alignItems:'center',flex:1}}><View style={[s.stepDot,i<=step&&{backgroundColor:C.green}]}><Txt color={i<=step?'#fff':C.muted} size={12} bold>{i+1}</Txt></View><Txt size={11} color={i===step?C.green:C.muted}>{x}</Txt></View>)}</View>
 {step===0&&<><Heading title="Tell us about your home" subtitle="Questions are configured for this service."/>{service.fields.map(key=><View key={key} style={{marginBottom:15}}><Txt bold style={{marginBottom:8}}>{fieldLabels[key]}</Txt><View style={s.wrap}>{options[key].map(value=><Chip key={value} label={value} selected={req[key]===value} onPress={()=>setReq({...req,[key]:value})}/>)}</View></View>)}{service.addons.length>0&&<><Heading title="Add a little extra"/>{service.addons.map(a=><TouchableOpacity key={a.id} onPress={()=>toggle(a.id)} style={s.addon}><Txt>{addons.includes(a.id)?'☑':'□'}  {a.name}</Txt><Txt color={C.green} bold>+{money(a.price)}</Txt></TouchableOpacity>)}</>}<Field label="Special instructions (optional)" placeholder="Anything we should know?"/><Card><Txt bold>Photo notes</Txt><Txt color={C.muted}>Optional photo placeholder · no gallery access in this demo.</Txt></Card><Btn title="Choose a time" onPress={()=>{const missing=service.fields.filter((key:FieldKey)=>!req[key]);if(missing.length){Alert.alert('A few details are missing','Please select: '+missing.map((key:FieldKey)=>fieldLabels[key]).join(', '));return}setStep(1)}}/></>}
 {step===1&&<><Heading title="Choose your visit" subtitle="Select a date first, then an arrival time."/><Card style={s.calendarCard}><View style={s.rowBetween}><View><Txt bold>Available dates</Txt><Txt size={12} color={C.muted}>Bookings start after the service lead time.</Txt></View><Txt size={12} color={C.green} bold>{service.leadDays===0?'Same-day available':'Plan ahead'}</Txt></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.dateRail}>{scheduleDays.map(d=><TouchableOpacity key={d.label} style={[s.dateTile,date===d.label&&s.dateTileOn]} onPress={()=>{setDate(d.label);const firstFree=service.slots.find(t=>!occupied(d.label,t));if(firstFree)setSlot(firstFree)}}><Txt size={11} color={date===d.label?'#fff':C.muted} bold>{d.weekday}</Txt><Txt size={22} color={date===d.label?'#fff':C.ink} bold>{d.day}</Txt><Txt size={11} color={date===d.label?'#e3f5df':C.muted}>{d.month}</Txt></TouchableOpacity>)}</ScrollView></Card><Heading title="Choose an arrival time" subtitle="Your cleaner will confirm before travelling."/><View style={s.timeGrid}>{service.slots.map(t=><TouchableOpacity key={t} disabled={occupied(date,t)} style={[s.timeTile,slot===t&&s.timeTileOn,occupied(date,t)&&s.timeTileDisabled]} onPress={()=>setSlot(t)}><Txt size={14} color={slot===t?'#fff':C.ink} bold>{t}</Txt><Txt size={11} color={slot===t?'#e3f5df':C.muted}>{occupied(date,t)?'Filled':'Available'}</Txt></TouchableOpacity>)}</View><Card style={{marginTop:14}}><Txt bold>What happens next</Txt><Txt size={13} color={C.muted} style={{marginTop:5}}>We match an eligible cleaner. They review and accept the job before you see live visit updates.</Txt></Card><Btn title="Add service address" onPress={()=>setStep(2)}/></>}
 {step===2&&<><Heading title="Where should we arrive?"/><TouchableOpacity style={s.location} onPress={()=>{setHouse('12B');setStreet('Demo lane');setArea('Adyar');setCity('Chennai');setPin('600020');Alert.alert('Demo location','Sample address filled locally. No location permission was requested.')}}><Txt color={C.green}>⌖  Use current location · simulated only</Txt></TouchableOpacity><Field label="House / flat number" value={house} onChangeText={setHouse}/><Field label="Street" value={street} onChangeText={setStreet}/><Field label="Area" value={area} onChangeText={setArea}/><Field label="City" value={city} onChangeText={setCity}/><Field label="PIN code" value={pin} onChangeText={setPin} keyboardType="number-pad"/><Field label="Landmark (optional)" value={landmark} onChangeText={setLandmark}/><Heading title="Contact person"/><Field label="Name" value={name} onChangeText={setName}/><Field label="Mobile number" value={phone} onChangeText={setPhone} keyboardType="phone-pad"/><Btn title="Review booking" onPress={()=>setStep(3)}/></>}
 {step===3&&<><Heading title="Review your booking" subtitle={`${date} · ${slot} · ${service.duration} min`}/><Card><Txt bold>{service.name}</Txt><Txt color={C.muted} style={{marginTop:4}}>{Object.entries(req).map(([k,v])=>`${fieldLabels[k as FieldKey]}: ${v}`).join(' · ')||'Standard service'}</Txt><Txt color={C.muted} style={{marginTop:8}}>{house}, {street}, {area}, {city} {pin}</Txt><Txt color={C.muted}>{name} · {phone}</Txt></Card><Heading title="Price breakdown"/>{price.lines.map((line,i)=><View style={s.priceLine} key={i}><Txt color={C.muted}>{line.label}</Txt><Txt bold>{line.amount<0?'−':''}{money(Math.abs(line.amount))}</Txt></View>)}<View style={[s.priceLine,{borderTopWidth:1,borderColor:C.line,paddingTop:14,marginTop:8}]}><Txt size={18} bold>Total</Txt><Txt size={20} color={C.green} bold>{money(price.total)}</Txt></View><Txt size={12} color={C.muted} style={{marginVertical:10}}>Payment integration coming later · no payment collected.</Txt><Btn title={user?'Confirm demo booking':'Sign in to confirm'} onPress={confirm}/><TouchableOpacity style={{padding:15,alignItems:'center'}} onPress={()=>setStep(2)}><Txt color={C.green}>Edit address</Txt></TouchableOpacity></>}
 </Screen><Modal visible={guestAuth} transparent animationType="slide"><View style={s.scrim}><View style={s.sheet}><Txt size={23} bold>Sign in to confirm</Txt><Txt color={C.muted} style={{marginVertical:8}}>Your booking details are saved here while you verify. Demo only · no SMS sent.</Txt>{!otp&&<Field label="Phone number" value={phone} onChangeText={setPhone} keyboardType="phone-pad"/>}{otp!==''&&<Field label="Any six-digit demo OTP" value={otp} onChangeText={setOtp} keyboardType="number-pad"/>}<Btn title={otp?'Verify and place booking':'Continue with phone'} onPress={()=>{if(!otp){if(!/^\d{10}$/.test(phone)){Alert.alert('Enter a 10-digit phone number');return}setOtp(' ')}else if(!/^\d{6}$/.test(otp)){Alert.alert('Enter any six digits');return}else{setUser({name,phone});setGuestAuth(false);create()}}}/><TouchableOpacity onPress={()=>setGuestAuth(false)} style={{padding:14,alignItems:'center'}}><Txt color={C.green}>Return to booking</Txt></TouchableOpacity></View></View></Modal></>}

function Empty({text}:any){return <Card style={{alignItems:'center',padding:28}}><Txt size={26}>✦</Txt><Txt bold style={{marginTop:8}}>{text}</Txt></Card>}
function BookingsPage({navigation}:any){const {bookings}=useMarketplace();return <Screen><Header title="My bookings" back={()=>navigation.goBack()}/><Txt color={C.muted}>Your demo appointments, all in one place.</Txt><Heading title="Upcoming & past"/>{bookings.length?bookings.map(b=><TouchableOpacity key={b.id} onPress={()=>navigation.navigate('Detail',{bookingId:b.id})}><BookingCard b={b}/></TouchableOpacity>):<Empty text="Your bookings will show up here."/>}<Btn title="Explore services" onPress={()=>navigation.navigate('Home')}/></Screen>}
function BookingCard({b}:any){return <Card style={{marginBottom:10}}><View style={s.rowBetween}><Txt bold>{b.serviceName}</Txt><Txt color={C.green} bold>{money(b.total)}</Txt></View><Txt color={C.muted} style={{marginTop:5}}>{b.id} · {b.date} at {b.slot}</Txt><View style={s.badge}><Txt size={12} color={C.green} bold>{statusText(b.status)}</Txt></View></Card>}
function BookingDetail({route,navigation}:any){
 const {bookings,applications,changeStatus}=useMarketplace();
 const b=bookings.find(x=>x.id===route.params.bookingId);
 if(!b)return <Screen><Empty text="Booking not found."/></Screen>;
 const cleaner=applications.find(a=>a.id===b.employeeId);
 const stages:[Booking['status'],string][]=[['awaiting_assignment','Finding a cleaner'],['awaiting_employee_acceptance','Cleaner confirms'],['assigned','Booking accepted'],['en_route','On the way'],['arrived','Arrived'],['in_progress','Cleaning in progress'],['completed','Completed']];
 const active=Math.max(0,stages.findIndex(([status])=>status===b.status));
 const liveCopy:Record<string,string>={awaiting_assignment:'We are checking nearby approved cleaners who can take this visit.',awaiting_employee_acceptance:'We found a cleaner and are waiting for confirmation.',assigned:'Your cleaner has accepted this booking.',en_route:'Your cleaner is travelling to your address.',arrived:'Your cleaner has arrived.',in_progress:'Your service is underway.',completed:'Your service is complete.'};
 const cancel=()=>Alert.alert('Cancel this booking?','This demo booking will be marked cancelled.',[{text:'Keep booking',style:'cancel'},{text:'Cancel booking',style:'destructive',onPress:()=>{changeStatus(b.id,'cancelled');navigation.goBack()}}]);
 return <Screen><Header title="Booking details" back={()=>navigation.goBack()}/><BookingCard b={b}/><Heading title="Live visit tracking" subtitle="Updates appear when your cleaner takes the next action."/><Card style={s.trackingCard}>{stages.map(([status,label],index)=><View key={status} style={s.trackRow}><View style={[s.trackDot,index<=active&&b.status!=='cancelled'&&s.trackDotOn]}/><View style={{flex:1}}><Txt bold={index===active} color={index<=active&&b.status!=='cancelled'?C.ink:C.muted}>{label}</Txt>{index===active&&<Txt size={12} color={C.green} style={{marginTop:2}}>{liveCopy[b.status]||statusText(b.status)}</Txt>}</View></View>)}</Card><Heading title="Appointment"/><Card><Txt bold>{b.date} · {b.slot}</Txt><Txt color={C.muted} style={{marginTop:5}}>{b.address}</Txt></Card><Card><Txt bold>{cleaner?`${cleaner.name} is handling your visit`:'Finding a suitable cleaner'}</Txt><Txt color={C.muted} style={{marginTop:5}}>{cleaner?`Skills: ${cleaner.skills.join(', ')} · Service area: ${cleaner.area}`:'We match approved active cleaners by service skill, area, availability and schedule.'}</Txt><Txt size={12} color={C.muted} style={{marginTop:8}}>Location tracking is simulated in this prototype. The cleaner updates their journey status from their dashboard.</Txt></Card><Heading title="Your selections"/>{Object.entries(b.requirements).map(([k,v])=><Txt key={k} style={s.bullet}>{fieldLabels[k as FieldKey]} · {v}</Txt>)}{b.addons.map(x=><Txt key={x} style={s.bullet}>Add-on · {x}</Txt>)}<Heading title="Price snapshot"/>{b.breakdown.map((x,i)=><View key={i} style={s.priceLine}><Txt color={C.muted}>{x.label}</Txt><Txt>{money(x.amount)}</Txt></View>)}<Heading title="Updates"/>{b.timeline.map((x,i)=><Txt key={i} style={s.bullet}>●  {x}</Txt>)}{!['cancelled','completed','in_progress'].includes(b.status)&&<Btn title="Cancel booking" secondary onPress={cancel}/>}</Screen>}
function EmployeePage({navigation}:any){const {applications,addApplication,bookings,changeStatus}=useMarketplace();const [name,setName]=useState('');const [phone,setPhone]=useState('');const [area,setArea]=useState('Adyar');const [experience,setExperience]=useState('');const [consent,setConsent]=useState(false);const [skills,setSkills]=useState<string[]>(['home']);const [chosen,setChosen]=useState<string|null>(null);const found=applications.find(a=>a.id===chosen)||applications.find(a=>a.phone===phone);const jobs=bookings.filter(b=>b.employeeId===found?.id);const [hours,setHours]=useState('09:00–18:00');
 return <Screen><Header title="Cleaner community" back={()=>navigation.goBack()}/><Card><Txt size={21} bold>Good work starts with care.</Txt><Txt color={C.muted} style={{marginTop:6}}>Join a local team that takes pride in the details.</Txt></Card>{found?<><Heading title={found.name} subtitle={`Application · ${found.status}`}/><Card><Txt bold>{found.status==='Pending'?'We’ve received your application.':found.status==='Approved'?'Your demo profile is approved.':'Your application was not approved.'}</Txt><Txt color={C.muted} style={{marginTop:6}}>Skills: {found.skills.join(', ')} · {found.area} · {found.hours}</Txt><Txt size={12} color={C.muted} style={{marginTop:9}}>Identity check: placeholder only · Bank/payment: placeholder only. Do not submit real documents or account information.</Txt></Card>{found.status==='Approved'&&<><Heading title="Your assigned jobs" subtitle="Demo earnings · no payouts"/>{jobs.length?jobs.map(b=><Card key={b.id} style={{marginBottom:10}}><Txt bold>{b.serviceName}</Txt><Txt color={C.muted} style={{marginTop:5}}>{b.date} · {b.slot} · {b.area}</Txt><Txt color={C.muted}>{b.id} · {money(b.total*.4)} estimated</Txt><View style={s.wrap}>{([['assigned','Accept job'],['en_route','On the way'],['arrived','Arrived'],['in_progress','Start job'],['completed','Complete']] as [Booking['status'],string][]).map(([st,label])=><Chip key={st} label={label} onPress={()=>changeStatus(b.id,st)} selected={b.status===st}/>)}</View></Card>):<Empty text="No assigned jobs yet."/>}</>}</>:<><Heading title="Apply to join" subtitle="Demo application · no real identity or bank details"/><Field label="Full name" value={name} onChangeText={setName}/><Field label="Phone number" value={phone} onChangeText={setPhone} keyboardType="phone-pad"/><Btn title="Open existing demo profile" secondary onPress={()=>{const a=applications.find(x=>x.phone===phone);if(a)setChosen(a.id);else Alert.alert("No demo profile found","Submit an application first.")}}/><Txt bold>Services you can do</Txt><View style={s.wrap}>{[['home','Home clean'],['bath','Bathroom'],['kitchen','Kitchen'],['tank','Tank'],['sofa','Sofa']].map(([id,label])=><Chip key={id} label={label} selected={skills.includes(id)} onPress={()=>setSkills(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id])}/>)}</View><Field label="Experience" value={experience} onChangeText={setExperience} placeholder="e.g. 2 years"/><Field label="Service area" value={area} onChangeText={setArea}/><Field label="Preferred working hours" value={hours} onChangeText={setHours}/><Card><Txt bold>Verification · demo placeholder</Txt><Txt color={C.muted}>No document upload or real identity information collected.</Txt><Txt bold style={{marginTop:8}}>Bank information · demo placeholder</Txt><Txt color={C.muted}>Not collected in this prototype.</Txt></Card><TouchableOpacity style={{paddingVertical:14}} onPress={()=>setConsent(!consent)}><Txt color={C.green}>{consent?'☑':'□'}  I agree this is a local demo application.</Txt></TouchableOpacity><Btn title="Submit demo application" onPress={()=>{if(!name.trim()||!/^\d{10}$/.test(phone)||!area.trim()||!consent){Alert.alert('Complete the application','Name, 10-digit number, area and consent are required.');return}const id=`EMP-${Date.now().toString().slice(-5)}`;addApplication({id,name,phone,skills,experience,area,hours,status:'Pending',active:false});setChosen(id)}}/></>}</Screen>}

function AdminGate({navigation}:any){const [entered,setEntered]=useState(false);return entered?<AdminDashboard navigation={navigation}/>:<Screen><Header title="Admin demo access" back={()=>navigation.goBack()}/><Card><Txt size={23} bold>Operations dashboard</Txt><Txt color={C.muted} style={{marginTop:7}}>Manage sample services, bookings, and cleaner applications in this local demo.</Txt><Txt size={12} color={C.muted} style={{marginTop:12}}>Demo-only access · no password or production authorization.</Txt></Card><Btn title="Enter Demo Admin" onPress={()=>setEntered(true)}/></Screen>}
function AdminDashboard({navigation}:any){const {services,bookings,applications,activities,saveService,assign,approve,changeStatus,updateEmployeeStatus}=useMarketplace();const [tab,setTab]=useState('Overview');const [filter,setFilter]=useState('All');const [query,setQuery]=useState('');const employees=applications.filter(a=>a.status==='Approved'&&a.active);const pending=applications.filter(a=>a.status==='Pending');const shownBookings=bookings.filter(b=>(filter==='All'||b.status===filter)&&(`${b.id} ${b.serviceName} ${b.area}`.toLowerCase().includes(query.toLowerCase())));return <Screen><View style={s.adminHead}><View><Txt size={12} color="#c9dfd3">TIDYDAY · OPERATIONS</Txt><Txt size={24} color="#fff" bold>Admin studio</Txt></View><TouchableOpacity onPress={()=>navigation.navigate('Home')}><Txt color="#fff">Exit</Txt></TouchableOpacity></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{maxHeight:48,marginTop:14}}>{['Overview','Bookings','Services','Team','Offers','Customers','Activity'].map(t=><Chip key={t} label={t} selected={tab===t} onPress={()=>setTab(t)}/>)}</ScrollView>
 {tab==='Overview'&&<><Heading title="Today at a glance" subtitle="Live totals from this demo session"/><View style={s.metricGrid}>{[['Bookings',bookings.length],['Unassigned',bookings.filter(b=>!b.employeeId&&b.status!=='cancelled').length],['Active team',employees.length],['Applications',pending.length]].map(([l,n])=><Card key={l} style={s.metric}><Txt size={25} bold>{n}</Txt><Txt color={C.muted}>{l}</Txt></Card>)}</View><Card><Txt bold>Mock revenue · completed work</Txt><Txt size={24} color={C.green} bold style={{marginTop:5}}>{money(bookings.filter(b=>b.status==='completed').reduce((s,b)=>s+b.total,0))}</Txt></Card><Heading title="Recent bookings"/>{bookings.slice(0,4).map(b=><BookingCard key={b.id} b={b}/>)}</>}
 {tab==='Bookings'&&<><Heading title="Bookings" subtitle="Search, assign and update jobs"/><TextInput style={s.search} value={query} onChangeText={setQuery} placeholder="Search booking, service, area"/><View style={s.wrap}>{['All','awaiting_assignment','assigned','in_progress','completed','cancelled'].map(x=><Chip key={x} label={x.replaceAll('_',' ')} selected={filter===x} onPress={()=>setFilter(x)}/>)}</View>{shownBookings.length?shownBookings.map(b=><Card key={b.id} style={{marginBottom:12}}><View style={s.rowBetween}><Txt bold>{b.serviceName}</Txt><Txt color={C.green} bold>{money(b.total)}</Txt></View><Txt color={C.muted} style={{marginVertical:5}}>{b.id} · {b.customerName} · {b.phone}</Txt><Txt color={C.muted}>{b.date} {b.slot} · {b.area} · {b.status.replaceAll('_',' ')}</Txt><Txt size={12} color={C.muted} style={{marginTop:4}}>{b.address}</Txt>{!b.employeeId&&<><Txt bold style={{marginTop:10}}>Eligible demo cleaners</Txt>{employees.filter(e=>e.skills.includes(b.serviceId)||e.skills.includes('home')).map(e=><TouchableOpacity key={e.id} style={s.assignBtn} onPress={()=>{const conflict=bookings.some(x=>x.id!==b.id&&x.employeeId===e.id&&x.date===b.date&&x.slot===b.slot&&!(['cancelled','completed'].includes(x.status)));if(conflict){Alert.alert('Schedule conflict','This cleaner already has a job in the same window. Choose another cleaner or time.');return}assign(b.id,e.id)}}><Txt color={C.green} bold>Assign {e.name} · {e.area}</Txt></TouchableOpacity>)}{employees.length===0&&<Txt color={C.red}>No approved active cleaner available.</Txt>}</>}<View style={s.wrap}>{([['en_route','On the way'],['arrived','Arrived'],['in_progress','Start'],['completed','Complete'],['cancelled','Cancel']] as [Booking['status'],string][]).map(([st,label])=><Chip key={st} label={label} selected={b.status===st} onPress={()=>changeStatus(b.id,st)}/>)}</View></Card>):<Empty text="No bookings match this filter."/>}</>}
 {tab==='Services'&&<><View style={s.rowBetween}><Heading title="Services" subtitle="Changes appear in the catalogue now"/><TouchableOpacity onPress={()=>navigation.navigate('EditService',{service:null})}><Txt color={C.green} bold>＋ Add</Txt></TouchableOpacity></View>{services.map(service=><Card key={service.id} style={{marginBottom:10}}><View style={s.rowBetween}><Txt bold>{service.name}</Txt><Txt color={C.green} bold>{money(service.price)}</Txt></View><Txt color={C.muted}>{service.category} · {service.duration} min · {service.active?(service.paused?'Paused':'Active'):'Inactive'}</Txt><View style={s.wrap}><Btn title="Edit" secondary onPress={()=>navigation.navigate('EditService',{service})}/><Btn title={service.active?'Deactivate':'Activate'} secondary onPress={()=>saveService({...service,active:!service.active})}/><Btn title={service.paused?'Resume':'Pause'} secondary onPress={()=>saveService({...service,paused:!service.paused})}/></View></Card>)}</>}
 {tab==='Team'&&<><Heading title="Applications" subtitle="Verification status is placeholder only"/>{applications.map(a=><Card key={a.id} style={{marginBottom:10}}><View style={s.rowBetween}><Txt bold>{a.name}</Txt><Txt color={a.status==='Approved'?C.green:C.orange}>{a.status}</Txt></View><Txt color={C.muted}>{a.phone} · {a.skills.join(', ')} · {a.area}</Txt><Txt size={12} color={C.muted}>Experience: {a.experience} · Hours: {a.hours} · Verification: demo placeholder</Txt>{a.status==='Pending'&&<View style={s.wrap}><Btn title="Approve" onPress={()=>approve(a.id,'Approved')}/><Btn title="Reject" secondary onPress={()=>Alert.alert('Reject this application?','This demo application will be marked rejected.',[{text:'Keep',style:'cancel'},{text:'Reject',style:'destructive',onPress:()=>approve(a.id,'Rejected')}])}/></View>}{a.status==='Approved'&&<Btn title={a.active?'Deactivate':'Activate'} secondary onPress={()=>updateEmployeeStatus(a.id,!a.active)}/>}</Card>)}</>}
 {tab==='Offers'&&<><Heading title="Offers & discounts" subtitle="Edit a service to change its discount"/>{services.map(service=><Card key={service.id}><View style={s.rowBetween}><Txt bold>{service.name}</Txt><Txt color={C.green} bold>{service.discount||0}% off</Txt></View><Txt color={C.muted}>Applies to new quotes · illustrative demo offer</Txt><Btn title="Edit offer" secondary onPress={()=>navigation.navigate('EditService',{service})}/></Card>)}</>}
  {tab==='Customers'&&<><Heading title="Customers" subtitle="Derived from customer bookings"/>{[...new Map(bookings.map(b=>[b.phone,b])).values()].map(b=><Card key={b.phone}><Txt bold>{b.customerName}</Txt><Txt color={C.muted}>{b.phone} · {bookings.filter(x=>x.phone===b.phone).length} booking(s)</Txt></Card>)}{bookings.length===0&&<Empty text="Customers appear after the first booking."/>}</>}
 {tab==='Activity'&&<><Heading title="Activity log" subtitle="Service, booking and team updates"/>{activities.map(a=><Card key={a.id} style={{marginBottom:8}}><Txt>{a.message}</Txt><Txt size={12} color={C.muted}>{a.time}</Txt></Card>)}{activities.length===0&&<Empty text="Activity will appear as you use the demo."/>}</>}
 <Card style={{marginTop:18}}><Txt size={12} color={C.muted}>Demo admin mode · client-side role switching is not production authorization.</Txt></Card></Screen>}

function ServiceEditor({route,navigation}:any){const {saveService}=useMarketplace();const orig=route.params.service as Service|null;const [name,setName]=useState(orig?.name||'');const [category,setCategory]=useState(orig?.category||'Home');const [price,setPrice]=useState(String(orig?.price||''));const [duration,setDuration]=useState(String(orig?.duration||120));const [lead,setLead]=useState(String(orig?.leadDays??1));const [discount,setDiscount]=useState(String(orig?.discount||0));const [desc,setDesc]=useState(orig?.description||'');const [slotText,setSlotText]=useState(orig?.slots.join(', ')||'09:00, 13:00');const [days,setDays]=useState<number[]>(orig?.weekdays||[1,2,3,4,5,6]);const [fieldSet,setFieldSet]=useState<FieldKey[]>(orig?.fields||['condition']);const fields:FieldKey[]=['property','occupancy','bhk','area','floors','bathrooms','condition'];const dayLabels=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return <Screen><Header title={orig?'Edit service':'New service'} back={()=>navigation.goBack()}/><Txt color={C.muted}>Illustrative prices · changes take effect immediately.</Txt><Field label="Service name" value={name} onChangeText={setName}/><Field label="Description" value={desc} onChangeText={setDesc}/><Txt bold>Category</Txt><View style={s.wrap}>{['Home','Room','Specialty','Fabric'].map(x=><Chip key={x} label={x} selected={category===x} onPress={()=>setCategory(x)}/>)}</View><Field label="Base price (₹)" value={price} onChangeText={setPrice} keyboardType="number-pad"/><Field label="Estimated duration (minutes)" value={duration} onChangeText={setDuration} keyboardType="number-pad"/><Field label="Minimum lead time (days)" value={lead} onChangeText={setLead} keyboardType="number-pad"/><Field label="Discount (%)" value={discount} onChangeText={setDiscount} keyboardType="number-pad"/><Heading title="Booking questions" subtitle="Select fields shown to customers"/><View style={s.wrap}>{fields.map(f=><Chip key={f} label={fieldLabels[f]} selected={fieldSet.includes(f)} onPress={()=>setFieldSet(v=>v.includes(f)?v.filter(x=>x!==f):[...v,f])}/>)}</View><Heading title="Availability rules" subtitle="Local demo schedule · one booking per service slot"/><Field label="Arrival slots, comma separated (HH:MM)" value={slotText} onChangeText={setSlotText} placeholder="09:00, 13:00"/><Txt bold>Available weekdays</Txt><View style={s.wrap}>{dayLabels.map((x,i)=><Chip key={x} label={x} selected={days.includes(i)} onPress={()=>setDays(v=>v.includes(i)?v.filter(d=>d!==i):[...v,i])}/>)}</View><Btn title="Save service" onPress={()=>{const n=Number(price),d=Number(duration),slots=slotText.split(',').map(x=>x.trim());if(!name.trim()||!desc.trim()||!Number.isFinite(n)||n<100||!Number.isFinite(d)||d<15||fieldSet.length===0||days.length===0||slots.some(x=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(x))){Alert.alert('Check service details','Add a name, description, valid price and duration, one booking question, at least one weekday, and valid 24-hour slots.');return}const service:Service={...(orig||{id:`service-${Date.now()}`,category,active:true,weekdays:days,slots,addons:[],includes:['General surface clean'],excludes:['Repairs']}),name,category,description:desc,price:n,duration:d,leadDays:Math.max(0,Number(lead)||0),discount:Math.min(100,Math.max(0,Number(discount)||0)),fields:fieldSet,weekdays:days,slots};saveService(service);Alert.alert('Saved',`${name} is updated in the customer catalogue.`);navigation.goBack()}}/></Screen>}
